  'help.guide.school-holidays.tip.1':
    'Нет региона? Администратор может вести школьные каникулы вручную в разделе Администрирование, Персонализация, Школьные каникулы.',
  // weekends
  'help.guide.weekends.title': 'Блокировать выходные и задать начало недели',
