  'help.guide.leave-year.step.1': 'Откройте Настройки и найдите Отпускной год.',
  'help.guide.leave-year.step.2':
    'Выберите Календарный, Финансовый (с месяцем и днём начала) или Дата приёма (с датой, когда вас приняли на работу).',
