  'help.guide.carry-over.tip.1': 'Выключение обнуляет каждый перенесённый остаток.',
  // invite
  'help.guide.invite.title': 'Планировать вместе с кем-то',
  'help.guide.invite.goal':
    'Объединить свой план с другим пользователем TREK, чтобы видеть выходные друг друга в одной сетке.',
