  // ── Screen: atlas ─────────────────────────────────────────────────────────────────────
  'help.ctx.atlas.title': 'Atlas',
  'help.ctx.atlas.summary':
    'Atlas показывает ваш след путешествий на карте мира: каждая страна, куда вас привела поездка, закрашена, а страны до TREK вы добавляете вручную. Приблизьте карту, чтобы увидеть регионы, ведите список желаний мест, которые ещё хотите увидеть, и читайте свои цифры в стеклянной панели внизу.',
  'help.ctx.atlas.bullet.1':
    'Карта: посещённые страны носят свой постоянный цвет, запланированные обведены пунктиром, страны из списка желаний заштрихованы по диагонали, всё остальное серое. Наведите курсор на страну, чтобы увидеть её поездки, места, первый и последний визит.',
  'help.ctx.atlas.bullet.2':
    'Поиск сверху: введите страну или место. Выбор страны переносит карту туда и открывает её окно; выбор места приземляет в его регион, чтобы вы могли его отметить.',
  'help.ctx.atlas.bullet.3':
    'Показать запланированные страны, справа сверху: показывает страны ваших предстоящих поездок. Переключатель появляется, только пока они есть.',
  'help.ctx.atlas.bullet.4':
    'Панель внизу: вкладка Статистика со странами, поездками, местами, городами, днями, континентами и вашей серией; вкладка Список желаний с тем, что ещё впереди.',
  'help.ctx.atlas.bullet.5':
    'Регионы: с 5-го уровня приближения карта переключается на штаты и провинции, каждый можно щёлкнуть, чтобы отметить или удалить.',
  'help.ctx.atlas.bullet.6':
    'Dawarich: с подключённым дополнением панель слева от статистики отмечает желания и добавляет страны из ваших записей, никогда без вашего подтверждения.',
  // mark-country
  'help.guide.mark-country.title': 'Отметить страну как посещённую',
  'help.guide.mark-country.goal': 'Добавьте страну, где вы были до TREK, чтобы карта и счётчик её учли.',
  'help.guide.mark-country.step.1': 'Введите страну в поле поиска вверху карты.',
  'help.guide.mark-country.step.2': 'Выберите её из списка. Карта перелетит туда, и откроется окно этой страны.',
  'help.guide.mark-country.step.3': 'Выберите Отметить как посещённую.',
  'help.guide.mark-country.result':
    'Страна получает свой цвет на карте, а Стран становится на одну больше. Цвет постоянный: отметка новых стран никогда не перемешивает остальные.',
  'help.guide.mark-country.tip.1':
    'Щелчок по серой стране на карте открывает то же окно; для маленьких стран надёжнее всего поиск.',
  'help.guide.mark-country.tip.2':
    'Страна, отмеченная вручную, всегда считается посещённой, какими бы ни были даты поездки туда.',
  // unmark-country
  'help.guide.unmark-country.title': 'Удалить отмеченную страну',
  'help.guide.unmark-country.goal': 'Снимите с карты страну, отмеченную вручную.',
  'help.guide.unmark-country.step.1':
    'Найдите страну и выберите её или щёлкните по ней на карте. Для страны, которую вы отметили сами, окно спросит, удалить ли её.',
  'help.guide.unmark-country.step.2': 'Подтвердите кнопкой Удалить.',
  'help.guide.unmark-country.result': 'Страна снова становится серой и уходит из счётчика.',
  'help.guide.unmark-country.tip.1':
    'Так удаляются только страны, отмеченные вручную. Страна с поездками или местами остаётся, пока они есть; Удалить есть и в её карточке в панели, если она была отмечена вручную.',
  // country-details
  'help.guide.country-details.title': 'Посмотреть, что вы делали в стране',
  'help.guide.country-details.goal': 'Откройте посещённую страну и перейдите к поездкам, которые вас туда привели.',
