    'В редакторе найдите Плюсы и минусы под историей. Впишите пункт в Плюсы или Минусы и используйте Добавить ещё для следующего.',
  'help.guide.pros-cons.step.2': 'Сохранить. Вердикт показывается на карточке двумя короткими списками.',
  'help.guide.pros-cons.result': 'Палец вверх и палец вниз с первого взгляда, под историей.',
  'help.guide.pros-cons.tip.1':
    'Путешествие, где вердикты не нужны, может отключить раздел в Поля записи в Настройках путешествия.',
  // search-journey
  'help.guide.search-journey.title': 'Найти что-то в длинном дневнике',
  'help.guide.search-journey.goal': 'Доберитесь до нужной записи, не листая недели.',
  'help.guide.search-journey.step.1':
    'Введите текст в Поиск по этому дневнику на панели инструментов. Хронология фильтруется по мере ввода, по заголовкам, историям, местам и тегам. Диакритика и регистр не важны.',
  'help.guide.search-journey.step.2':
    'Переключатель предложений в шапке скрывает ненаписанные карточки, пока вы читаете. Когда хронология длинная, над её нижним краем плавают две круглые кнопки: наверх и к последней записи.',
