  'help.guide.gallery-map.step.1':
    'Переключитесь на Галерея на панели инструментов: каждое фото каждой записи плюс снимки, загруженные прямо в галерею. Щёлкните одно для лайтбокса.',
  'help.guide.gallery-map.step.2':
    'Карта справа показывает записи как метки в порядке дат, места привязанных поездок и любой GPX-трек, импортированный в эти поездки, в том цвете, что у него в планировщике.',
  'help.guide.gallery-map.result':
    'Наведите на трек, чтобы увидеть его название. Пунктир между записями рисует TREK; трек: маршрут, который вы действительно записали.',
